function FeaturesGrid() {
  const features = [
    { icon: '⚡', title: 'Lightning Fast', description: 'Optimized for speed with sub-second load times and instant responses.' },
    { icon: '🔒', title: 'Secure by Default', description: 'Enterprise-grade security with encryption and compliance built in.' },
    { icon: '📱', title: 'Mobile First', description: 'Designed for any device with responsive layouts and touch support.' },
    { icon: '🔄', title: 'Real-time Sync', description: 'Keep everything in sync across all your devices automatically.' },
    { icon: '🎨', title: 'Customizable', description: 'Tailor every aspect to match your brand and workflow.' },
    { icon: '💬', title: '24/7 Support', description: 'Expert help whenever you need it with our dedicated team.' }
  ];

  return (
    <section className="py-24 bg-white">
      <div className="max-w-7xl mx-auto px-6">
        <div className="text-center mb-16">
          <h2 className="text-4xl font-bold text-gray-900 mb-4">Everything you need</h2>
          <p className="text-xl text-gray-600 max-w-2xl mx-auto">Powerful features to help you manage your workflow efficiently</p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {features.map((feature, index) => (
            <div key={index} className="p-8 rounded-2xl bg-gray-50 hover:bg-gray-100 transition-colors">
              <div className="text-4xl mb-4">{feature.icon}</div>
              <h3 className="text-xl font-semibold text-gray-900 mb-2">{feature.title}</h3>
              <p className="text-gray-600 leading-relaxed">{feature.description}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

